// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAiProviders The Learner's saved AI Providers
	// (GET /ai-providers)
	ListAiProviders(ctx context.Context, request ListAiProvidersRequestObject) (ListAiProvidersResponseObject, error)
	// CreateAiProvider Save a new AI Provider
	// (POST /ai-providers)
	CreateAiProvider(ctx context.Context, request CreateAiProviderRequestObject) (CreateAiProviderResponseObject, error)
	// DeleteAiProvider Remove an AI Provider
	// (DELETE /ai-providers/{id})
	DeleteAiProvider(ctx context.Context, request DeleteAiProviderRequestObject) (DeleteAiProviderResponseObject, error)
	// GetAiProvider One AI Provider
	// (GET /ai-providers/{id})
	GetAiProvider(ctx context.Context, request GetAiProviderRequestObject) (GetAiProviderResponseObject, error)
	// UpdateAiProvider Change an AI Provider
	// (PATCH /ai-providers/{id})
	UpdateAiProvider(ctx context.Context, request UpdateAiProviderRequestObject) (UpdateAiProviderResponseObject, error)
	// TestAiProvider Check that the provider answers a tiny chat request
	// (POST /ai-providers/{id}/test)
	TestAiProvider(ctx context.Context, request TestAiProviderRequestObject) (TestAiProviderResponseObject, error)
	// ListAiTasks Which AI Provider each task uses
	// (GET /ai-tasks)
	ListAiTasks(ctx context.Context, request ListAiTasksRequestObject) (ListAiTasksResponseObject, error)
	// ClearAiTask Leave a task without an AI Provider
	// (DELETE /ai-tasks/{task})
	ClearAiTask(ctx context.Context, request ClearAiTaskRequestObject) (ClearAiTaskResponseObject, error)
	// SetAiTask Choose the AI Provider for a task
	// (PUT /ai-tasks/{task})
	SetAiTask(ctx context.Context, request SetAiTaskRequestObject) (SetAiTaskResponseObject, error)
	// Login Exchange a username and password for a session token
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Invalidate the current session token
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ListGrammarPoints Grammar points in catalogue order (level N5→N1, then catalogue number)
	// (GET /grammar/points)
	ListGrammarPoints(ctx context.Context, request ListGrammarPointsRequestObject) (ListGrammarPointsResponseObject, error)
	// GetGrammarPoint Read a grammar point, generating missing content on first read
	// (GET /grammar/points/{id})
	GetGrammarPoint(ctx context.Context, request GetGrammarPointRequestObject) (GetGrammarPointResponseObject, error)
	// UpdateGrammarPoint Edit the explanation of a grammar point
	// (PATCH /grammar/points/{id})
	UpdateGrammarPoint(ctx context.Context, request UpdateGrammarPointRequestObject) (UpdateGrammarPointResponseObject, error)
	// GenerateGrammarExamples Generate example sentences, validating each against JMdict before storing it
	// (POST /grammar/points/{id}/examples)
	GenerateGrammarExamples(ctx context.Context, request GenerateGrammarExamplesRequestObject) (GenerateGrammarExamplesResponseObject, error)
	// RegenerateGrammarExplanation Regenerate the explanation, replacing any existing one
	// (POST /grammar/points/{id}/explanation/regenerate)
	RegenerateGrammarExplanation(ctx context.Context, request RegenerateGrammarExplanationRequestObject) (RegenerateGrammarExplanationResponseObject, error)
	// ListGrammarReviewItems MaruMori grammar the Learner knows that the Catalogue Matching could not resolve cleanly
	// (GET /grammar/review)
	ListGrammarReviewItems(ctx context.Context, request ListGrammarReviewItemsRequestObject) (ListGrammarReviewItemsResponseObject, error)
	// GetHealth Liveness and database connectivity check
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetMaruMoriStatus Whether MaruMori is connected, and what the last Sync found
	// (GET /marumori)
	GetMaruMoriStatus(ctx context.Context, request GetMaruMoriStatusRequestObject) (GetMaruMoriStatusResponseObject, error)
	// DeleteMaruMoriKey Stop the MaruMori connection and forget the key
	// (DELETE /marumori/key)
	DeleteMaruMoriKey(ctx context.Context, request DeleteMaruMoriKeyRequestObject) (DeleteMaruMoriKeyResponseObject, error)
	// SetMaruMoriKey Store the Learner's MaruMori API key
	// (PUT /marumori/key)
	SetMaruMoriKey(ctx context.Context, request SetMaruMoriKeyRequestObject) (SetMaruMoriKeyResponseObject, error)
	// SyncMaruMori Sync the Learner's knowledge state from MaruMori now
	// (POST /marumori/sync)
	SyncMaruMori(ctx context.Context, request SyncMaruMoriRequestObject) (SyncMaruMoriResponseObject, error)
	// ListMaruMoriSyncs The Learner's recent Sync runs, newest first
	// (GET /marumori/syncs)
	ListMaruMoriSyncs(ctx context.Context, request ListMaruMoriSyncsRequestObject) (ListMaruMoriSyncsResponseObject, error)
	// GetMe The authenticated user
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetStartingLevel The Learner's declared Starting Level, if they have chosen one
	// (GET /starting-level)
	GetStartingLevel(ctx context.Context, request GetStartingLevelRequestObject) (GetStartingLevelResponseObject, error)
	// SetStartingLevel Choose or change the Starting Level
	// (PUT /starting-level)
	SetStartingLevel(ctx context.Context, request SetStartingLevelRequestObject) (SetStartingLevelResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListAiProviders operation middleware
func (sh *strictHandler) ListAiProviders(w http.ResponseWriter, r *http.Request) {
	var request ListAiProvidersRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListAiProviders(ctx, request.(ListAiProvidersRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListAiProviders")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListAiProvidersResponseObject); ok {
		if err := validResponse.VisitListAiProvidersResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

